$controllersDir = "d:\E-Commerce\backend\src\main\java\com\ecommerce\controllers"
New-Item -ItemType Directory -Force -Path $controllersDir | Out-Null

$classes = @(
    @{ Name = "AuthController"; Content = "package com.ecommerce.controllers;`nimport com.ecommerce.dto.LoginRequest;`nimport com.ecommerce.dto.SignupRequest;`nimport com.ecommerce.services.AuthService;`nimport jakarta.validation.Valid;`nimport lombok.RequiredArgsConstructor;`nimport org.springframework.http.ResponseEntity;`nimport org.springframework.web.bind.annotation.*;`n@RestController`n@RequestMapping(`"/api/auth`")`n@RequiredArgsConstructor`npublic class AuthController {`n    private final AuthService authService;`n    @PostMapping(`"/signin`")`n    public ResponseEntity<?> authenticateUser(@Valid @RequestBody LoginRequest loginRequest) {`n        return ResponseEntity.ok(authService.authenticateUser(loginRequest));`n    }`n    @PostMapping(`"/signup`")`n    public ResponseEntity<?> registerUser(@Valid @RequestBody SignupRequest signUpRequest) {`n        return ResponseEntity.ok(authService.registerUser(signUpRequest));`n    }`n}" },
    @{ Name = "ProductController"; Content = "package com.ecommerce.controllers;`nimport com.ecommerce.models.Product;`nimport com.ecommerce.services.ProductService;`nimport lombok.RequiredArgsConstructor;`nimport org.springframework.http.ResponseEntity;`nimport org.springframework.security.access.prepost.PreAuthorize;`nimport org.springframework.web.bind.annotation.*;`nimport java.util.List;`n@RestController`n@RequestMapping(`"/api/products`")`n@RequiredArgsConstructor`npublic class ProductController {`n    private final ProductService productService;`n    @GetMapping`n    public ResponseEntity<List<Product>> getAllActiveProducts() {`n        return ResponseEntity.ok(productService.getAllActiveProducts());`n    }`n    @GetMapping(`"/search`")`n    public ResponseEntity<List<Product>> searchProducts(@RequestParam String keyword) {`n        return ResponseEntity.ok(productService.searchProducts(keyword));`n    }`n    @GetMapping(`"/{id}`")`n    public ResponseEntity<Product> getProductById(@PathVariable Long id) {`n        return ResponseEntity.ok(productService.getProductById(id));`n    }`n    @PostMapping`n    @PreAuthorize(`"hasRole('ADMIN')`")`n    public ResponseEntity<Product> createProduct(@RequestBody Product product) {`n        return ResponseEntity.ok(productService.createProduct(product));`n    }`n    @DeleteMapping(`"/{id}`")`n    @PreAuthorize(`"hasRole('ADMIN')`")`n    public ResponseEntity<?> deleteProduct(@PathVariable Long id) {`n        productService.deleteProduct(id);`n        return ResponseEntity.ok().build();`n    }`n}" },
    @{ Name = "CartController"; Content = "package com.ecommerce.controllers;`nimport com.ecommerce.dto.CartRequest;`nimport com.ecommerce.models.Cart;`nimport com.ecommerce.security.UserDetailsImpl;`nimport com.ecommerce.services.CartService;`nimport lombok.RequiredArgsConstructor;`nimport org.springframework.http.ResponseEntity;`nimport org.springframework.security.core.annotation.AuthenticationPrincipal;`nimport org.springframework.web.bind.annotation.*;`n@RestController`n@RequestMapping(`"/api/cart`")`n@RequiredArgsConstructor`npublic class CartController {`n    private final CartService cartService;`n    @GetMapping`n    public ResponseEntity<Cart> getCart(@AuthenticationPrincipal UserDetailsImpl userDetails) {`n        return ResponseEntity.ok(cartService.getCart(userDetails.getId()));`n    }`n    @PostMapping(`"/add`")`n    public ResponseEntity<Cart> addToCart(@AuthenticationPrincipal UserDetailsImpl userDetails, @RequestBody CartRequest request) {`n        return ResponseEntity.ok(cartService.addToCart(userDetails.getId(), request));`n    }`n}" },
    @{ Name = "OrderController"; Content = "package com.ecommerce.controllers;`nimport com.ecommerce.models.Order;`nimport com.ecommerce.security.UserDetailsImpl;`nimport com.ecommerce.services.OrderService;`nimport lombok.RequiredArgsConstructor;`nimport org.springframework.http.ResponseEntity;`nimport org.springframework.security.core.annotation.AuthenticationPrincipal;`nimport org.springframework.web.bind.annotation.*;`n@RestController`n@RequestMapping(`"/api/orders`")`n@RequiredArgsConstructor`npublic class OrderController {`n    private final OrderService orderService;`n    @PostMapping(`"/place/{addressId}`")`n    public ResponseEntity<Order> placeOrder(@AuthenticationPrincipal UserDetailsImpl userDetails, @PathVariable Long addressId) {`n        return ResponseEntity.ok(orderService.placeOrder(userDetails.getId(), addressId));`n    }`n    @GetMapping(`"/{orderId}`")`n    public ResponseEntity<Order> getOrder(@PathVariable Long orderId) {`n        return ResponseEntity.ok(orderService.getOrder(orderId));`n    }`n}" },
    @{ Name = "UserController"; Content = "package com.ecommerce.controllers;`nimport com.ecommerce.models.Address;`nimport com.ecommerce.models.User;`nimport com.ecommerce.security.UserDetailsImpl;`nimport com.ecommerce.services.UserService;`nimport lombok.RequiredArgsConstructor;`nimport org.springframework.http.ResponseEntity;`nimport org.springframework.security.core.annotation.AuthenticationPrincipal;`nimport org.springframework.web.bind.annotation.*;`nimport java.util.List;`n@RestController`n@RequestMapping(`"/api/user`")`n@RequiredArgsConstructor`npublic class UserController {`n    private final UserService userService;`n    @GetMapping(`"/profile`")`n    public ResponseEntity<User> getProfile(@AuthenticationPrincipal UserDetailsImpl userDetails) {`n        return ResponseEntity.ok(userService.getUserProfile(userDetails.getId()));`n    }`n    @PostMapping(`"/addresses`")`n    public ResponseEntity<Address> addAddress(@AuthenticationPrincipal UserDetailsImpl userDetails, @RequestBody Address address) {`n        return ResponseEntity.ok(userService.addAddress(userDetails.getId(), address));`n    }`n    @GetMapping(`"/addresses`")`n    public ResponseEntity<List<Address>> getAddresses(@AuthenticationPrincipal UserDetailsImpl userDetails) {`n        return ResponseEntity.ok(userService.getUserAddresses(userDetails.getId()));`n    }`n}" }
)

foreach ($class in $classes) {
    $path = "$controllersDir\$($class.Name).java"
    Set-Content -Path $path -Value $class.Content -Encoding UTF8
}
